import pygame
from constants import *

class Block:
    def __init__(self, x, y, btype, content=None, pipe_h=0, is_pipe_top=False):
        self.x = x
        self.y = y
        self.w = TILE
        self.h = TILE
        self.type = btype  # 'ground', 'brick', 'question', 'pipe'
        self.content = content  # 'coin', 'mushroom', 'star', 'fire_flower', None
        self.hit = False       # 方块已撞击
        self.broken = False    # 砖块已破碎
        self.bump_y = 0        # 顶砖动画偏移
        self.frame = 0
        # pipe特有
        self.pipe_h = pipe_h
        self.is_pipe_top = is_pipe_top

    def update(self):
        self.frame += 1
        # 顶砖反弹动画
        if self.bump_y < 0:
            self.bump_y += 1.5
            if self.bump_y > 0:
                self.bump_y = 0

    def hit_block(self):
        """从下方撞击方块，返回 'coin', 'mushroom', 'star', 'fire_flower', 'break', None"""
        if self.type == 'question' and not self.hit:
            self.hit = True
            self.bump_y = -8
            return self.content
        elif self.type == 'brick' and not self.hit:
            self.hit = True
            self.broken = True
            self.bump_y = -8
            return 'break'
        elif self.type == 'brick':
            self.bump_y = -4
            return None
        elif self.type == 'question' and self.hit:
            self.bump_y = -4
            return None
        return None

    def is_solid(self):
        if self.broken:
            return False
        if self.type == 'ground':
            return True
        if self.type == 'pipe':
            return True
        if self.type in ('brick', 'question'):
            return True
        return False

    def draw(self, surface, cam_x):
        if self.broken:
            return
        sx = self.x - int(cam_x)
        sy = self.y + self.bump_y

        if sx < -TILE or sx > SCREEN_W + TILE:
            return

        if self.type == 'ground':
            pygame.draw.rect(surface, BROWN, (sx, sy, self.w, self.h))
            pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)
            # 地面纹理线
            for i in range(0, self.w, 10):
                pygame.draw.line(surface, DARK_BROWN, (sx + i, sy), (sx + i, sy + self.h), 1)

        elif self.type == 'brick':
            if not self.hit:
                pygame.draw.rect(surface, BRICK_COLOR, (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)
                # 砖纹理
                pygame.draw.line(surface, DARK_BROWN, (sx, sy + self.h // 2), (sx + self.w, sy + self.h // 2), 2)
                pygame.draw.line(surface, DARK_BROWN, (sx + self.w // 2, sy), (sx + self.w // 2, sy + self.h // 2), 1)
            else:
                # 已顶过的砖变暗
                pygame.draw.rect(surface, (120, 70, 30), (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, DARK_BROWN, (sx, sy, self.w, self.h), 2)

        elif self.type == 'question':
            if not self.hit:
                pygame.draw.rect(surface, QUESTION_COLOR, (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, (180, 150, 30), (sx, sy, self.w, self.h), 2)
                # ? 标记
                font = pygame.font.SysFont("Arial", 22, bold=True)
                q = font.render("?", True, WHITE)
                surface.blit(q, (sx + 12, sy + 8))
            else:
                pygame.draw.rect(surface, (120, 100, 30), (sx, sy, self.w, self.h))
                pygame.draw.rect(surface, (80, 60, 20), (sx, sy, self.w, self.h), 2)

        elif self.type == 'pipe':
            # 只画当前格子大小的管道体，不重复画整根管道
            pygame.draw.rect(surface, PIPE_COLOR, (sx + 2, sy + (8 if not self.is_pipe_top else 0), 
                                                     self.w - 4, TILE - (8 if not self.is_pipe_top else 0)))
            # 管道口（仅顶部块）
            if self.is_pipe_top:
                lip_h = 8
                pygame.draw.rect(surface, PIPE_DARK, (sx - 4, sy, self.w + 8, lip_h))
                pygame.draw.rect(surface, PIPE_COLOR, (sx - 4 + 2, sy + 1, self.w + 8 - 4, lip_h - 2))
            # 边框
            pygame.draw.rect(surface, PIPE_DARK, (sx + 2, sy + (8 if not self.is_pipe_top else 0),
                                                    self.w - 4, TILE - (8 if not self.is_pipe_top else 0)), 1)

    def get_rect(self):
        return pygame.Rect(self.x, self.y + int(self.bump_y), self.w, self.h)

    def get_top_rect(self):
        return pygame.Rect(self.x, self.y + int(self.bump_y), self.w, 4)

    def get_bottom_rect(self):
        return pygame.Rect(self.x + 2, self.y + int(self.bump_y) - 4, self.w - 4, 8)

