                    self.x = sr.left - self.w
                elif self.vx < 0:
                    self.x = sr.right
                self.vx = -self.vx
                return

    def _collide_y(self, solids):
        rect = pygame.Rect(int(self.x), int(self.y), self.w, self.h)
        for s in solids:
            sr = pygame.Rect(int(s.x), int(s.y), s.w, s.h) if not isinstance(s, pygame.Rect) else s
            if rect.colliderect(sr):
                if self.vy > 0:
                    self.y = sr.top - self.h
                    self.vy = 0
                elif self.vy < 0:
                    self.y = sr.bottom
